const queryTypes = yield* Database.resolve('dxn:org.dxos.operation.assistantToolkit.queryTypes');
const querySkills = yield* Database.resolve('dxn:org.dxos.operation.assistantToolkit.querySkills');
const queryOps = yield* Database.resolve('dxn:org.dxos.operation.assistantToolkit.queryOperations');

const types = yield* Operation.invoke(queryTypes, { typenames: ['com.example.type.task'] });
yield* print('TYPES', types);

const skills = yield* Operation.invoke(querySkills, {});
yield* print('SKILLS', skills);

const ops = yield* Operation.invoke(queryOps, { query: 'score task priority ranking' });
yield* print('OPS', ops);

